ance>=0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(member_id,currency_id,unit), FOREIGN KEY(member_id) REFERENCES members(id), FOREIGN KEY(currency_id) REFERENCES club_currencies(id));CREATE TABLE club_draw_early_closures (promotion_slug TEXT PRIMARY KEY, closed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reason TEXT NOT NULL, closed_by TEXT NOT NULL, original_end TEXT NOT NULL);CREATE TABLE club_draw_review_numbers (promotion_id INTEGER NOT NULL,code TEXT NOT NULL,PRIMARY KEY(promotion_id,code));CREATE TABLE club_draw_reviews (promotion_id INTEGER PRIMARY KEY,unit TEXT NOT NULL,reviewed_at TEXT NOT NULL,participants INTEGER NOT NULL,eligible INTEGER NOT NULL,excluded INTEGER NOT NULL,number_count INTEGER NOT NULL,contract_synced_at TEXT NOT NULL);CREATE TABLE club_equipment (id INTEGER PRIMARY KEY AUTOINCREMENT,unit TEXT NOT NULL,type TEXT NOT NULL,serial TEXT NOT NULL,identifier TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(unit,serial));CREATE TABLE club_equipment_issues (id INTEGER PRIMARY KEY AUTOINCREMENT,unit TEXT NOT NULL,label TEXT NOT NULL,UNIQUE(unit,label));CREATE TABLE club_equipment_maintenance (id INTEGER PRIMARY KEY AUTOINCREMENT,unit TEXT NOT NULL,equipment_id INTEGER NOT NULL,issue_id INTEGER NOT NULL,side TEXT,room_position TEXT,status TEXT NOT NULL DEFAULT 'pending',opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,notes TEXT,FOREIGN KEY(equipment_id) REFERENCES club_equipment(id));CREATE TABLE club_evo_import_batches (id TEXT PRIMARY KEY,unit TEXT NOT NULL CHECK(unit IN ('bike','gym')),branch_code TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'prepared' CHECK(state IN ('prepared','partial','confirmed','review')),created_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TEXT, snapshot_json TEXT NOT NULL DEFAULT '[]', return_json TEXT NOT NULL DEFAULT '[]');CREATE TABLE club_evo_import_items (order_id TEXT PRIMARY KEY,unit TEXT