);CREATE TABLE conquest_tv_display (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, target INTEGER NOT NULL, earned_date TEXT NOT NULL, displayed_date TEXT NOT NULL, session_id TEXT NOT NULL, displayed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,evo_member_id,target,earned_date));CREATE TABLE conquest_tv_settings (unit TEXT PRIMARY KEY, show_empty INTEGER NOT NULL DEFAULT 0, positions_seconds INTEGER NOT NULL DEFAULT 15, highlights_seconds INTEGER NOT NULL DEFAULT 10, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_attendance_import_queue(unit TEXT NOT NULL,id_activity_session TEXT NOT NULL,activity_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,PRIMARY KEY(unit,id_activity_session));CREATE TABLE evo_attendance_import_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,unit TEXT,period_from TEXT,period_to TEXT,status TEXT,requests INTEGER DEFAULT 0,classes_found INTEGER DEFAULT 0,classes_done INTEGER DEFAULT 0,presences_saved INTEGER DEFAULT 0,started_at TEXT DEFAULT CURRENT_TIMESTAMP,finished_at TEXT);CREATE TABLE evo_attendance_sessions (unit TEXT NOT NULL,id_activity_session TEXT NOT NULL,activity_date TEXT NOT NULL,start_time TEXT,activity_name TEXT,status TEXT NOT NULL DEFAULT 'done',attendance_count INTEGER NOT NULL DEFAULT 0,synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, instructor_name TEXT,PRIMARY KEY(unit,id_activity_session));CREATE TABLE evo_contract_catalog (tenant_key TEXT NOT NULL, unit TEXT NOT NULL, evo_contract_id TEXT NOT NULL, contract_name TEXT NOT NULL, category_id TEXT, category_name TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), source TEXT NOT NULL DEFAULT 'evo', first_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_synced_at TEXT, inactive_since TEXT, PRIMARY KEY (tenant_key, unit, evo_contract_id));CREATE TABLE evo_contract_catalog_sync (tenant_key TEXT NOT NULL, unit TEXT NOT NULL, last_attempt_at TEXT, last_success_at TEXT, last_result TEXT, last_count INTEGER, last_error TEXT, PRIMARY KEY(tenant_key,unit));CREATE TABLE evo_contract_categories (tenant_key TEXT NOT NULL, unit TEXT NOT NULL, category_id TEXT NOT NULL, category_name TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'evo', last_synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(tenant_key,unit,category_id));CREATE TABLE evo_contract_sync_checkpoint(unit TEXT PRIMARY KEY,next_skip INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_contract_sync_generation(unit TEXT PRIMARY KEY,run_id TEXT NOT NULL,next_skip INTEGER NOT NULL DEFAULT 0,completed INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_current_runs (id TEXT PRIMARY KEY, unit TEXT NOT NULL CHECK(unit='bike'), state TEXT NOT NULL, next_skip INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, report_ids TEXT, added INTEGER DEFAULT 0, changed INTEGER DEFAULT 0, removed INTEGER DEFAULT 0, error TEXT, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_current_runs_v2 (id TEXT PRIMARY KEY, unit TEXT NOT NULL CHECK(unit IN ('bike','gym')), state TEXT NOT NULL, next_skip INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, report_ids TEXT, added INTEGER DEFAULT 0, changed INTEGER DEFAULT 0, removed INTEGER DEFAULT 0, error TEXT, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_current_stage (run_id TEXT NOT NULL REFERENCES evo_current_runs(id), evo_member_id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(run_id,evo_member_id));CREATE TABLE evo_current_stage_v2 (run_id TEXT NOT NULL REFERENCES evo_current_runs_v2(id), evo_member_id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(run_id,evo_member_id));CREATE TABLE evo_daily_registration_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,unit TEXT NOT NULL,day TEXT NOT NULL,category TEXT NOT NULL,found INTEGER NOT NULL,inserted INTEGER NOT NULL,requests INTEGER NOT NULL,status TEXT NOT NULL,error TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_daily_registrations (unit TEXT NOT NULL, category TEXT NOT NULL, evo_id TEXT NOT NULL, register_day TEXT NOT NULL, register_at TEXT, display_name TEXT, payload_json TEXT NOT NULL, first_seen_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,category,evo_id));CREATE TABLE evo_instructor_backfill_attempts(unit TEXT NOT NULL,id_activity_session TEXT NOT NULL,attempted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL,detail TEXT,PRIMARY KEY(unit,id_activity_session));CREATE TABLE evo_member_attendance (unit TEXT NOT NULL,evo_member_id TEXT NOT NULL,attendance_key TEXT NOT NULL,attendance_date TEXT NOT NULL,start_time TEXT,activity_name TEXT,id_activity_session TEXT,raw_json TEXT NOT NULL,synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(unit,evo_member_id,attendance_key));CREATE TABLE evo_member_attendance_states (unit TEXT NOT NULL,evo_member_id TEXT NOT NULL,id_activity_session TEXT NOT NULL,attendance_date TEXT NOT NULL,start_time TEXT,activity_name TEXT,evo_status INTEGER NOT NULL,justified_absence INTEGER,raw_json TEXT NOT NULL,synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(unit,evo_member_id,id_activity_session));CREATE TABLE evo_member_cache (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, payload_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,evo_member_id));CREATE TABLE evo_member_contracts (
