CREATE TABLE evo_modalities_catalog_sync (unit TEXT PRIMARY KEY,last_success_at TEXT,last_count INTEGER,last_requests INTEGER);CREATE TABLE evo_product_catalog (tenant_key TEXT NOT NULL DEFAULT 'default',unit TEXT NOT NULL CHECK(unit IN ('bike','gym')),evo_product_id TEXT NOT NULL,name TEXT NOT NULL,sku TEXT,barcode TEXT,price_cents INTEGER,stock_quantity REAL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),raw_json TEXT NOT NULL,last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_key,unit,evo_product_id));CREATE TABLE evo_product_sync (tenant_key TEXT NOT NULL DEFAULT 'default',unit TEXT NOT NULL CHECK(unit IN ('bike','gym')),last_attempt_at TEXT,last_success_at TEXT,last_count INTEGER NOT NULL DEFAULT 0,last_error TEXT,request_count INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_key,unit));CREATE TABLE evo_prospect_reservations(unit TEXT NOT NULL,session_id TEXT NOT NULL,prospect_id TEXT NOT NULL,activity_date TEXT NOT NULL,start_time TEXT NOT NULL,activity_name TEXT,member_name TEXT,status TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(unit,session_id,prospect_id));CREATE TABLE evo_request_log (id INTEGER PRIMARY KEY AUTOINCREMENT, unit TEXT NOT NULL, purpose TEXT NOT NULL DEFAULT 'other', method TEXT NOT NULL DEFAULT 'GET', endpoint TEXT NOT NULL DEFAULT '', status INTEGER, ok INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_reservation_jobs(unit TEXT PRIMARY KEY,run_key TEXT NOT NULL,state TEXT NOT NULL,payload TEXT NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_service_catalog (unit TEXT NOT NULL CHECK(unit IN ('bike','gym')), evo_service_id TEXT NOT NULL, service_name TEXT NOT NULL, price REAL, is_active INTEGER NOT NULL DEFAULT 1, raw_json TEXT NOT NULL, last_synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,evo_service_id));CREATE TABLE evo_service_catalog_sync (unit TEXT PRIMARY KEY CHECK(unit IN ('bike','gym')), last_success_at TEXT, last_count INTEGER NOT NULL DEFAULT 0);CREATE TABLE evo_session_contract_reconciliation (unit TEXT NOT NULL,evo_member_id TEXT NOT NULL,id_activity_session TEXT NOT NULL,contract_key TEXT,session_date TEXT NOT NULL,session_time TEXT,confidence TEXT NOT NULL CHECK(confidence IN ('probable_unique','ambiguous','unmatched')),candidate_count INTEGER NOT NULL,source TEXT NOT NULL DEFAULT 'd1_date_active_contract',reconciled_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(unit,evo_member_id,id_activity_session));CREATE TABLE evo_student_categories (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, category TEXT NOT NULL, subtype TEXT NOT NULL DEFAULT '', source TEXT NOT NULL, PRIMARY KEY(unit,evo_member_id,category,subtype), FOREIGN KEY(unit,evo_member_id) REFERENCES evo_students(unit,evo_member_id));CREATE TABLE evo_student_sync_log (id INTEGER PRIMARY KEY AUTOINCREMENT, unit TEXT NOT NULL, added INTEGER NOT NULL DEFAULT 0, changed INTEGER NOT NULL DEFAULT 0, removed INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_student_sync_stage (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, payload_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,evo_member_id));CREATE TABLE evo_student_sync_state (unit TEXT PRIMARY KEY, next_skip INTEGER NOT NULL DEFAULT 0, links_processed INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_students (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, display_name TEXT NOT NULL, membership_status TEXT NOT NULL, fitcoins REAL, is_current INTEGER NOT NULL, last_run TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,evo_member_id));CREATE TABLE evo_sync_config (unit TEXT PRIMARY KEY, sync_time TEXT NOT NULL DEFAULT '04:00', enabled INTEGER NOT NULL DEFAULT 1, last_sync_at TEXT, last_sync_status TEXT, last_sync_requests INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_sync_payload_diagnostic (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, payload_json TEXT NOT NULL, captured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,evo_member_id));CREATE TABLE evo_sync_probe (id INTEGER PRIMARY KEY, endpoint TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', result_json TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_sync_schedule_runs(unit TEXT NOT NULL,kind TEXT NOT NULL,scheduled_minute TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',detail TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(unit,kind,scheduled_minute));CREATE TABLE evo_sync_schedules(unit TEXT NOT NULL,kind TEXT NOT NULL,times_json TEXT NOT NULL DEFAULT '[]',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(unit,kind));CREATE TABLE evo_unit_config (unit TEXT PRIMARY KEY, dns TEXT NOT NULL DEFAULT '', token TEXT NOT NULL DEFAULT '', expires_at TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE evo_vip_diagnostic_checkpoint (unit TEXT PRIMARY KEY, next_skip INTEGER NOT NULL DEFAULT 0, contracts INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, vip_json TEXT NOT NULL DEFAULT '[]', details_json TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE gym_member_links (     id INTEGER PRIMARY KEY AUTOINCREMENT,     gym_client_id TEXT NOT NULL UNIQUE,     member_id INTEGER NOT NULL,     link_source TEXT,     linked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     status TEXT NOT NULL DEFAULT 'ACTIVE',     FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE );CREATE TABLE import_batches (     id INTEGER PRIMARY KEY AUTOINCREMENT,     import_type TEXT NOT NULL,     filename TEXT,     file_hash TEXT,     reference_month TEXT,     total_rows INTEGER NOT NULL DEFAULT 0,     valid_rows INTEGER NOT NULL DEFAULT 0,     unmatched_rows INTEGER NOT NULL DEFAULT 0,     duplicate_rows INTEGER NOT NULL DEFAULT 0,     error_rows INTEGER NOT NULL DEFAULT 0,     status TEXT NOT NULL DEFAULT 'PROCESSING',     created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     completed_at TEXT );CREATE TABLE landing_v2_content(slot TEXT PRIMARY KEY, content_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE lucky_audit_snapshots(unit TEXT NOT NULL,evo_id TEXT NOT NULL,kind TEXT NOT NULL,scope TEXT NOT NULL,payload TEXT NOT NULL,checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(unit,evo_id,kind,scope));CREATE TABLE lucky_draw_audit_results(promotion_id TEXT NOT NULL,unit TEXT NOT NULL,evo_id TEXT NOT NULL,member_ids TEXT NOT NULL,eligible INTEGER NOT NULL,expected INTEGER NOT NULL,existing INTEGER NOT NULL,details_json TEXT NOT NULL,checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(promotion_id,unit,evo_id));CREATE TABLE lucky_draw_events(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL,stage TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE lucky_draw_leases(lease_key TEXT PRIMARY KEY,token TEXT NOT NULL,expires_at TEXT NOT NULL);CREATE TABLE lucky_draw_pool(run_id TEXT NOT NULL,promotion_id TEXT NOT NULL,unit TEXT NOT NULL,code TEXT NOT NULL,member_id TEXT NOT NULL,evo_id TEXT NOT NULL,PRIMARY KEY(run_id,promotion_id,code));CREATE TABLE lucky_draw_preparation(promotion_id TEXT PRIMARY KEY,stage TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE lucky_draw_runs(id TEXT PRIMARY KEY,promotion_id TEXT NOT NULL UNIQUE,linked_id TEXT,scheduled_at TEXT NOT NULL,cutoff_at TEXT,stage TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',pool_hash TEXT,winner_code TEXT,winner_unit TEXT,winner_member TEXT,completed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE lucky_number_reconciliations(id INTEGER PRIMARY KEY AUTOINCREMENT,promotion_id INTEGER NOT NULL,number_id INTEGER NOT NULL,code TEXT NOT NULL,member_id INTEGER NOT NULL,unit TEXT NOT NULL,reason TEXT NOT NULL,details_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE lucky_numbers (     id INTEGER PRIMARY KEY AUTOINCREMENT,     promotion_id INTEGER NOT NULL,     participant_id INTEGER NOT NULL,     attendance_id INTEGER,     bonus_award_id INTEGER,     code TEXT NOT NULL,     reference_month TEXT NOT NULL,     studio TEXT NOT NULL,     origin TEXT NOT NULL,     status TEXT NOT NULL DEFAULT 'ACTIVE',     issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     cancelled_at TEXT,     UNIQUE (promotion_id, code),     FOREIGN KEY (promotion_id) REFERENCES promotions(id),     FOREIGN KEY (participant_id) REFERENCES promotion_participants(id),     FOREIGN KEY (attendance_id) REFERENCES promotion_attendance(id),     FOREIGN KEY (bonus_award_id) REFERENCES promotion_bonus_awards(id) );CREATE TABLE members (   id INTEGER PRIMARY KEY AUTOINCREMENT,   evo_member_id INTEGER UNIQUE,   gym_client_id TEXT UNIQUE,   cpf_hash TEXT NOT NULL UNIQUE,   cpf_last4 TEXT,   first_name TEXT,   last_name TEXT,   email TEXT,   birth_date TEXT,   pin_hash TEXT,   pin_salt TEXT,   pin_created_at TEXT,   status TEXT NOT NULL DEFAULT 'ACTIVE',   failed_login_attempts INTEGER NOT NULL DEFAULT 0,   locked_until TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , presencas_legadas_bike INTEGER NOT NULL DEFAULT 0 CHECK (presencas_legadas_bike >= 0), presencas_legadas_gym INTEGER NOT NULL DEFAULT 0 CHECK (presencas_legadas_gym >= 0));CREATE TABLE mission_progress (     id INTEGER PRIMARY KEY AUTOINCREMENT,     member_id INTEGER NOT NULL,     mission_key TEXT NOT NULL,     reference_period TEXT NOT NULL,     progress INTEGER NOT NULL DEFAULT 0,     goal INTEGER NOT NULL,     status TEXT NOT NULL DEFAULT 'IN_PROGRESS',     updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     UNIQUE (member_id, mission_key, reference_period),     FOREIGN KEY (member_id) REFERENCES members(id) );CREATE TABLE partner_campaign_events(id INTEGER PRIMARY KEY AUTOINCREMENT,benefit_id TEXT NOT NULL,unit TEXT NOT NULL,member_id TEXT NOT NULL,event_type TEXT NOT NULL,day TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(benefit_id,unit,member_id,event_type,day));CREATE TABLE partner_code_vouchers(benefit_id TEXT NOT NULL,unit TEXT NOT NULL,member_id TEXT NOT NULL,member_name TEXT NOT NULL,code TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,used_at TEXT,PRIMARY KEY(benefit_id,unit,member_id));CREATE TABLE partner_daily_redemptions(id INTEGER PRIMARY KEY AUTOINCREMENT,benefit_id TEXT NOT NULL,unit TEXT NOT NULL,member_id TEXT NOT NULL,member_name TEXT NOT NULL,partner_name TEXT NOT NULL,benefit_title TEXT NOT NULL,local_date TEXT NOT NULL,used_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(benefit_id,unit,member_id,local_date));CREATE TABLE partner_once_redemptions(id INTEGER PRIMARY KEY AUTOINCREMENT,benefit_id TEXT NOT NULL,unit TEXT NOT NULL,member_id TEXT NOT NULL,member_name TEXT NOT NULL,partner_name TEXT NOT NULL,benefit_title TEXT NOT NULL,used_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(benefit_id,unit,member_id));CREATE TABLE pop_draw_classes(draw_id TEXT NOT NULL,unit TEXT NOT NULL,session_id TEXT NOT NULL,activity_date TEXT NOT NULL,PRIMARY KEY(draw_id,unit,session_id));CREATE TABLE pop_draw_entries(draw_id TEXT NOT NULL,number TEXT NOT NULL,member_id TEXT NOT NULL,member_name TEXT NOT NULL,attendance_ref TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(draw_id,number),FOREIGN KEY(draw_id) REFERENCES pop_draws(id));CREATE TABLE pop_draw_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,draw_id TEXT NOT NULL,action TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE pop_draw_metadata(draw_id TEXT PRIMARY KEY,prize_type TEXT,partner_id TEXT,partner_name TEXT,partner_whatsapp TEXT,prize_description TEXT);CREATE TABLE pop_draw_winners(draw_id TEXT NOT NULL,position INTEGER NOT NULL,number TEXT NOT NULL,member_id TEXT NOT NULL,member_name TEXT NOT NULL,drawn_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(draw_id,position),UNIQUE(draw_id,member_id),FOREIGN KEY(draw_id,number) REFERENCES pop_draw_entries(draw_id,number));CREATE TABLE pop_draws(id TEXT PRIMARY KEY,unit TEXT NOT NULL CHECK(unit IN ('bike','gym')),title TEXT NOT NULL,prize_name TEXT NOT NULL,prize_location TEXT NOT NULL,draw_at TEXT NOT NULL,winners_count INTEGER NOT NULL DEFAULT 1 CHECK(winners_count BETWEEN 1 AND 50),automatic INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','completed','cancelled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);CREATE TABLE pop_fit_entries(member_id INTEGER NOT NULL,unit TEXT NOT NULL,attendance_key TEXT NOT NULL,weight REAL,height REAL,calories INTEGER,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(member_id,unit,attendance_key));CREATE TABLE pop_fit_images(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER NOT NULL,scope TEXT NOT NULL,image_data TEXT NOT NULL,period_label TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE pop_fit_manual_activities(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER NOT NULL,activity_name TEXT NOT NULL,activity_date TEXT NOT NULL,start_time TEXT,calories INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE pop_fit_profile(member_id INTEGER PRIMARY KEY,height REAL,initial_weight REAL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE promotion_attendance (     id INTEGER PRIMARY KEY AUTOINCREMENT,     promotion_id INTEGER NOT NULL,     participant_id INTEGER NOT NULL,     studio TEXT NOT NULL,     occurred_at TEXT,     reference_month TEXT NOT NULL,     source TEXT NOT NULL,     source_ref TEXT,     status TEXT NOT NULL DEFAULT 'VALID',     created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     FOREIGN KEY (promotion_id) REFERENCES promotions(id),     FOREIGN KEY (participant_id) REFERENCES promotion_participants(id) );CREATE TABLE promotion_bonus_awards (     id INTEGER PRIMARY KEY AUTOINCREMENT,     promotion_id INTEGER NOT NULL,     participant_id INTEGER NOT NULL,     reference_month TEXT NOT NULL,     studio TEXT NOT NULL,     milestone INTEGER NOT NULL,     quantity INTEGER NOT NULL,     status TEXT NOT NULL DEFAULT 'ACTIVE',     created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     UNIQUE (         promotion_id,         participant_id,         reference_month,         studio,         milestone     ),     FOREIGN KEY (promotion_id) REFERENCES promotions(id),     FOREIGN KEY (participant_id) REFERENCES promotion_participants(id) );CREATE TABLE promotion_number_update_errors(id INTEGER PRIMARY KEY AUTOINCREMENT,promotion_slug TEXT NOT NULL,evo_member_id TEXT,student_name TEXT,error TEXT NOT NULL,checkpoint INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'PENDING', resolution_note TEXT, resolved_at TEXT);CREATE TABLE promotion_number_update_log(id INTEGER PRIMARY KEY AUTOINCREMENT,promotion_slug TEXT NOT NULL,unit TEXT NOT NULL DEFAULT 'bike',mode TEXT NOT NULL DEFAULT 'FULL',status TEXT NOT NULL,checked INTEGER NOT NULL DEFAULT 0,eligible INTEGER NOT NULL DEFAULT 0,with_attendance INTEGER NOT NULL DEFAULT 0,participants_updated INTEGER NOT NULL DEFAULT 0,generated INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,checkpoint INTEGER NOT NULL DEFAULT 0,evo_member_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE promotion_number_update_state(promotion_slug TEXT PRIMARY KEY,unit TEXT NOT NULL DEFAULT 'bike',next_skip INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'IN_PROGRESS',checked INTEGER NOT NULL DEFAULT 0,eligible INTEGER NOT NULL DEFAULT 0,with_attendance INTEGER NOT NULL DEFAULT 0,participants_updated INTEGER NOT NULL DEFAULT 0,generated INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE promotion_participants (     id INTEGER PRIMARY KEY AUTOINCREMENT,     promotion_id INTEGER NOT NULL,     member_id INTEGER NOT NULL,     created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     UNIQUE (promotion_id, member_id),     FOREIGN KEY (promotion_id) REFERENCES promotions(id),     FOREIGN KEY (member_id) REFERENCES members(id) );CREATE TABLE promotion_review_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,promotion_slug TEXT NOT NULL,member_id INTEGER NOT NULL,evo_member_id INTEGER,status TEXT NOT NULL DEFAULT 'PENDING',eligibility_snapshot TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE promotions (     id INTEGER PRIMARY KEY AUTOINCREMENT,     slug TEXT NOT NULL UNIQUE,     name TEXT NOT NULL,     description TEXT,     start_at TEXT NOT NULL,     end_at TEXT NOT NULL,     status TEXT NOT NULL DEFAULT 'DRAFT',     rules_json TEXT,     banner_url TEXT,     created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );CREATE TABLE redemptions (     id INTEGER PRIMARY KEY AUTOINCREMENT,     member_id INTEGER NOT NULL,     redemption_type TEXT NOT NULL,     reference_id TEXT,     fitcoins INTEGER NOT NULL DEFAULT 0,     status TEXT NOT NULL DEFAULT 'PENDING',     requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     approved_at TEXT,     completed_at TEXT,     cancelled_at TEXT, source_type TEXT, source_id TEXT, title TEXT, details TEXT, cash_amount REAL NOT NULL DEFAULT 0, unit TEXT, dedupe_key TEXT, handled_by TEXT, handled_at TEXT, cancel_reason TEXT,     FOREIGN KEY (member_id) REFERENCES members(id) );CREATE TABLE staff_users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,pin_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'reception',units_json TEXT NOT NULL DEFAULT '["bike"]',permissions_json TEXT NOT NULL DEFAULT '[]',enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, teacher_links_json TEXT NOT NULL DEFAULT '{}');CREATE TABLE student_issue_report_events (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 report_id INTEGER NOT NULL REFERENCES student_issue_reports(id),
 actor_type TEXT NOT NULL CHECK(actor_type IN ('student','admin')),
 actor_id TEXT NOT NULL,
 event_type TEXT NOT NULL,
 note TEXT,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, visibility TEXT NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','internal')));
CREATE TABLE student_issue_reports (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 member_id TEXT NOT NULL,
 evo_member_id TEXT,
 member_name TEXT NOT NULL,
 unit TEXT NOT NULL CHECK(unit IN ('bike','gym','club')),
 area TEXT NOT NULL,
 description TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'aberto' CHECK(status IN ('aberto','em_analise','aguardando_aluno','resolvido','encerrado')),
 priority TEXT NOT NULL DEFAULT 'media' CHECK(priority IN ('baixa','media','alta','critica')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 resolved_at TEXT
);CREATE TABLE student_management_dispatches(batch_id TEXT NOT NULL,phone TEXT NOT NULL,unit TEXT NOT NULL,group_name TEXT NOT NULL,flow INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(batch_id,phone));CREATE TABLE student_management_segments(id INTEGER PRIMARY KEY AUTOINCREMENT,unit TEXT NOT NULL CHECK(unit IN ('bike','gym')),name TEXT NOT NULL,filters_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE student_tutorial_videos (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL,unit TEXT NOT NULL DEFAULT 'all' CHECK(unit IN ('all','bike','gym')),drive_file_id TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,published INTEGER NOT NULL DEFAULT 1 CHECK(published IN (0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE teacher_payment_overrides (unit TEXT NOT NULL, id_activity_session TEXT NOT NULL, teacher_name TEXT, attendance_count INTEGER, capacity INTEGER, activity_name TEXT, teacher_absent INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,id_activity_session));CREATE TABLE teacher_payment_settings (unit TEXT NOT NULL, category TEXT NOT NULL, capacity INTEGER NOT NULL DEFAULT 34, ticket_cents INTEGER NOT NULL DEFAULT 1530, bands_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,category));CREATE TABLE teacher_weekly_payments (unit TEXT NOT NULL, month TEXT NOT NULL, week_start TEXT NOT NULL, week_end TEXT NOT NULL, teacher_key TEXT NOT NULL, teacher_name TEXT NOT NULL, paid INTEGER NOT NULL DEFAULT 0, paid_at TEXT, paid_amount_cents INTEGER, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,month,week_start,teacher_key));CREATE TABLE tv_campaign_events(id INTEGER PRIMARY KEY AUTOINCREMENT,campaign_id TEXT NOT NULL,kind TEXT NOT NULL,unit TEXT NOT NULL,visitor_key TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE tv_pop_config(unit TEXT PRIMARY KEY,config_json TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE unit_ui_config(unit TEXT PRIMARY KEY, background_color TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, logo_data TEXT, favicon_data TEXT, logo_link TEXT, header_color TEXT);CREATE TABLE useful_link_events (
  visit_id TEXT NOT NULL REFERENCES useful_link_visits(id) ON DELETE CASCADE,
  seq INTEGER NOT NULL CHECK(seq BETWEEN 1 AND 300),
  event TEXT NOT NULL,
  step INTEGER NOT NULL CHECK(step BETWEEN 0 AND 2),
  elapsed_ms INTEGER NOT NULL,
  received_at INTEGER NOT NULL,
  PRIMARY KEY(visit_id,seq)
);CREATE TABLE useful_link_rate_limits (
  bucket TEXT PRIMARY KEY,
  expires_at INTEGER NOT NULL,
  hits INTEGER NOT NULL DEFAULT 1
);CREATE TABLE useful_link_tracking_v2 (id INTEGER PRIMARY KEY AUTOINCREMENT, link_slug TEXT NOT NULL, session_id TEXT NOT NULL, event_type TEXT NOT NULL, step TEXT, period TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE useful_link_visits (
  id TEXT PRIMARY KEY,
  token_hash TEXT NOT NULL,
  link TEXT NOT NULL CHECK(link='aula-experimental'),
  created_at INTEGER NOT NULL,
  device TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT '',
  medium TEXT NOT NULL DEFAULT '',
  campaign TEXT NOT NULL DEFAULT '',
  referrer TEXT NOT NULL DEFAULT ''
);CREATE TABLE useful_links (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, target TEXT, config_json TEXT, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE vouchers (     id INTEGER PRIMARY KEY AUTOINCREMENT,     member_id INTEGER NOT NULL,     code TEXT NOT NULL UNIQUE,     type TEXT NOT NULL,     description TEXT,     status TEXT NOT NULL DEFAULT 'ACTIVE',     issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     expires_at TEXT,     redeemed_at TEXT, redemption_id INTEGER, source_type TEXT, source_id TEXT, title TEXT, metadata_json TEXT, used_by TEXT, cancelled_at TEXT,     FOREIGN KEY (member_id) REFERENCES members(id) );
